function adHands(t,hi){var src=hi?ADHI:ADLO,cols=0;src.forEach(function(l){if(l.length>cols)cols=l.length});var k0=(Math.sin(t*.45)+1)/2,off=Math.round(k0*(hi?3:2)),g=adShift(src,off,cols).map(function(l){return l.split("")});var ramp=".:-=+*#%@";for(var y=0;y<g.length;y++)for(var x=0;x<g[y].length;x++){if(g[y][x]!==" "&&Math.random()<.008)g[y][x]=ramp[Math.floor(Math.random()*ramp.length)]}var sy=Math.round(g.length*.45),sx=Math.round(cols*.495);if(k0>.55){var sp=k0>.85?"*":"+";if(g[sy])g[sy][sx]=sp;if(k0>.75){if(g[sy-1])g[sy-1][sx]="'";if(g[sy+1])g[sy+1][sx]=".";if(g[sy])g[sy][sx-1]="-",g[sy][sx+1]="-"}}return g.map(function(l){return l.join("")}).join("\n")}

