const ADF_1 = function adPlanet(t){var W=80,H=28,cx=W/2,cy=H/2,R=10.2,o="",x,y,ramp=" .,:;-=+*#%@",tilt=-.32;for(y=0;y<H;y++){for(x=0;x<W;x++){var dx=(x-cx)*.6/R,dy=(y-cy)/R,d2=dx*dx+dy*dy,c=" ";var ex=(x-cx)*.6,ey=(y-cy),rx=ex*Math.cos(tilt)-ey*Math.sin(tilt),ry=ex*Math.sin(tilt)+ey*Math.cos(tilt),e=Math.sqrt(rx*rx/(20*20)+ry*ry/(5*5));var ring=(e>.84&&e<1.02)&&!(e>.9&&e<.93);if(d2<1){var z=Math.sqrt(1-d2),a=t*.35,X=dx*Math.cos(a)+z*Math.sin(a),Z=-dx*Math.sin(a)+z*Math.cos(a),land=nz3(X*2.2,dy*2.2,Z*2.2),li=Math.max(0,-dx*.55-dy*.45+z*.7),v=.08+.92*li*(land>.15?1:.55);c=ramp[Math.min(11,Math.floor(v*11.99))];if(ring&&ry>0)c=(e>.95?"=":"-")}else if(ring){c=ry>0?(e>.95?"=":"-"):(e>.95?"-":".")}else if(((x*37+y*91)%97)===0)c=(Math.sin(t*2+x*y)>.2)?"*":".";o+=c}o+="\n"}return o};

