 for(y=2;y<=4;y++){put(hx+42,y,"|");put(hx+44,y,"|")}
 for(i=0;i<6;i++){var ph=(t*.8+i*1.2)%7,sy2=1-ph*.7,sx2=hx+43+Math.sin(ph*1.1+i)*1.4+ph*.9;if(sy2>=0)put(sx2,sy2,ph<2.5?"o":(ph<5?"O":"("))}
 /* Wi-Fi */
 var wv=Math.floor(t*2)%4;put(mx,0,"*");for(var a=1;a<=3;a++)if(a<=wv){put(mx+a*2,0,")");put(mx-a*2,0,"(")}
 /* корпус */
