const ADF_5 = function adOuro(t){var W=70,H=26,cx=W/2-.5,cy=H/2,R=9.2,th=1.9,o="",x,y,ramp=" .,:;-=+*%#@";for(y=0;y<H;y++){for(x=0;x<W;x++){var dx=(x-cx)*.5,dy=(y-cy),r=Math.sqrt(dx*dx+dy*dy),a=Math.atan2(dy,dx),c=" ";var rel=(a+Math.PI/2+2*Math.PI)%(2*Math.PI);var tk=th;if(rel>2*Math.PI-.9)tk=th*Math.max(.25,(2*Math.PI-rel)/.9);var hx=dx,hy=dy+R+.3,head=(hx*hx)/(4.4*4.4)+(hy*hy)/(2.7*2.7);if(head<1){var sh=Math.sqrt(1-head);c=ramp[Math.min(11,4+Math.floor(sh*8))];if(Math.abs(hx-1.6)<.6&&Math.abs(hy+.6)<.5)c="O";if(hx<-1.6&&Math.abs(hy-.2)<.45)c=" ";}else{var n=(r-R)/tk;if(Math.abs(n)<1&&!(rel<.25)){var u=rel*30/(2*Math.PI)*2-t*1.6,v=n*1.6,fa=((u+v)%1+1)%1,fb=((u-v)%1+1)%1,edge=Math.min(fa,1-fa,fb,1-fb)<.14,sh2=Math.sqrt(1-n*n)*(.55+.45*Math.cos(a+2.3));var k=Math.max(2,Math.min(11,3+Math.floor(sh2*8)-(edge?3:0)));c=ramp[k];}}o+=c}o+="\n"}return o};

