function adHelix(t){var W=74,H=30,g=[],zb=[],x,y,cx=W/2,R=17,ch;for(y=0;y<H;y++){g.push(new Array(W).fill(" "));zb.push(new Array(W).fill(-9))}function put(x,y,c,z){x=Math.round(x);if(x>=0&&x<W&&z>zb[y][x]){zb[y][x]=z;g[y][x]=c}}var B="ATGC";for(y=0;y<H;y++){var ph=y*.32+t*1.0,x1=cx+Math.cos(ph)*R,z1=Math.sin(ph),x2=cx+Math.cos(ph+Math.PI)*R,z2=-z1;if(y%3===0){var n=Math.round(Math.abs(x2-x1));for(var k=1;k<n;k++){var f=k/n,xx=x1+(x2-x1)*f,zz=z1+(z2-z1)*f;put(xx,y,zz>.3?"=":(zz>-.3?"-":"."),zz-.05)}var mid=(x1+x2)/2,mz=(z1+z2)/2;if(Math.abs(x2-x1)>6){put(mid-1,y,B[(y/3+Math.floor(t))%4],mz+.01);put(mid+1,y,B[(y/3+2+Math.floor(t))%4],mz+.01)}}[[x1,z1],[x2,z2]].forEach(function(p){var c=p[1]>.6?"@":p[1]>.2?"%":p[1]>-.2?"*":p[1]>-.6?"+":".";put(p[0],y,c,p[1]);put(p[0]-1,y,p[1]>.2?"(":".",p[1]-.02);put(p[0]+1,y,p[1]>.2?")":".",p[1]-.02)})}
for(var i=0;i<14;i++){var px=(i*29+Math.floor(t*3)*7)%W,py=(i*17)%H;if(g[py][px]===" "&&Math.sin(t*2+i)>.4)g[py][px]="·"}return g.map(function(l){return l.join("")}).join("\n")}

function adGear(t){var W=60,H=24,cx=W/2,cy=H/2,o="",x,y,ramp=" .,:;-=+*%#@",n=12;for(y=0;y<H;y++){for(x=0;x<W;x++){var dx=(x-cx)*.6,dy=(y-cy),r=Math.sqrt(dx*dx+dy*dy),a=Math.atan2(dy,dx)+t*.5,f=((a*n/(2*Math.PI))%1+1)%1,Ro=8.6+(f<.5?1.8:0),c=" ";if(r<Ro&&r>2.4){var hole=false;for(var k=0;k<5;k++){var aa=k*2*Math.PI/5-t*.5,hx=dx-Math.cos(aa)*5.2,hy=dy-Math.sin(aa)*5.2;if(hx*hx+hy*hy<2.6)hole=true}if(!hole){c=r>Ro-1.3?"#":(r<4?"@":((x+y)%2?"+":"="))}}o+=c}o+="\n"}return o}

function donut(A,B){var W=46,H=19,out=[],zb=[],i,j,k;for(k=0;k<W*H;k++){out[k]=" ";zb[k]=0}var cA=Math.cos(A),sA=Math.sin(A),cB=Math.cos(B),sB=Math.sin(B);for(j=0;j<6.28;j+=.09){var cj=Math.cos(j),sj=Math.sin(j);for(i=0;i<6.28;i+=.03){var ci=Math.cos(i),si=Math.sin(i),h=cj+2,D=1/(si*h*sA+sj*cA+5),t=si*h*cA-sj*sA,x=Math.floor(W/2+W*.5*D*(ci*h*cB-t*sB)),y=Math.floor(H/2+H*.6*D*(ci*h*sB+t*cB)),o=x+W*y,N=Math.floor(8*((sj*sA-si*cj*cA)*cB-si*cj*sA-sj*cA-ci*cj*sB));if(y>=0&&y<H&&x>=0&&x<W&&D>zb[o]){zb[o]=D;out[o]=".,-~:;=!*#$@"[N>0?N:0]}}}var r="";for(k=0;k<H;k++)r+=out.slice(k*W,k*W+W).join("")+"\n";return r}

function adTerrain(t){var W=76,H=22,g=[],x,y,r;for(y=0;y<H;y++)g.push(new Array(W).fill(" "));for(r=0;r<12;r++){var base=4+r*1.5;for(x=0;x<W;x++){var hgt=Math.exp(-Math.pow((x-W/2)/(W*.24),2))*(Math.sin(x*.31+t+r*.8)*1.1+Math.sin(x*.12-t*.6+r*.5)*2.4+2.8);var yy=Math.round(base-hgt*(.45+r*.07));if(yy>=0&&yy<H){g[yy][x]=r<4?".":(r<8?"-":"=");for(var k=yy+1;k<H&&k<yy+3;k++)g[k][x]=" "}}}return g.map(function(l){return l.join("")}).join("\n")}

function tkS(t){var dd=t/2.2,k=Math.floor(dd)%8,f=dd%1,e=f*f*(3-2*f),n=6,pr=k<6?(k+e)/n:(k===6?1:1-e),d=k<6?k:(k===6?6:Math.round(6*(1-e)));return {pr:pr,d:d,k:k,n:n,fin:k===6,e:e}}

function rnd(a,b){return a+Math.random()*(b-a)}

function SV(css,inner,vb,par){return '<svg viewBox="'+(vb||"0 0 200 100")+'" preserveAspectRatio="'+(par||"xMidYMax slice")+'" style="position:absolute;'+css+'">'+inner+'</svg>'}

function hill(y,col){return '<path d="M0 '+y+' Q40 '+(y-14)+' 80 '+(y-4)+' T160 '+(y-8)+' T240 '+y+' V100 H0Z" fill="'+col+'"/>'}

function treesRow(y,h,w,n,col){var p="",i;for(i=0;i<n;i++){var x=i*(200/n)+rnd(-3,3),hh=h*rnd(.7,1.2);p+="M"+x.toFixed(1)+" "+y+" L"+(x+w/2).toFixed(1)+" "+(y-hh).toFixed(1)+" L"+(x+w).toFixed(1)+" "+y+" Z ";}return '<path d="'+p+'" fill="'+col+'"/><rect x="0" y="'+(y-.5)+'" width="200" height="'+(101-y)+'" fill="'+col+'"/>'}

function waveG(y,amp,col,dur,op){var d="M0 "+y;for(var x=0;x<400;x+=50){d+=" Q"+(x+25)+" "+(y-amp)+" "+(x+50)+" "+y}d+=" V100 H0Z";return '<g style="animation:waveX '+dur+'s linear infinite"><path d="'+d+'" fill="'+col+'" opacity="'+(op||1)+'"/></g>'}

function flake(css){var a="",i;for(i=0;i<6;i++){a+='<g transform="rotate('+(i*60)+' 20 20)"><line x1="20" y1="20" x2="20" y2="3" /><line x1="20" y1="9" x2="16" y2="5"/><line x1="20" y1="9" x2="24" y2="5"/><line x1="20" y1="14" x2="17" y2="11"/><line x1="20" y1="14" x2="23" y2="11"/></g>'}return '<svg viewBox="0 0 40 40" style="position:absolute;'+css+'"><g stroke="#8fbcd9" stroke-width="1" stroke-linecap="round" fill="none">'+a+'</g></svg>'}

const ADF = [ADF_0, ADF_1, ADF_2, ADF_3, ADF_4, ADF_5, ADF_6, ADF_7, ADF_8, ADF_9, ADF_10];


export const ASCII_NAMES = ['Руки', 'Планета', 'Гора-цель', 'Схема связей', 'Ночной дом', 'Уроборос', 'Заметки', 'Спираль ДНК', 'Шестерёнка'];
// Кадр страницы pg (0..8) в момент t (секунды). На «Сегодня» руки крупные.
export function asciiFrame(pg, t) {
  try { return pg === 0 ? adHands(t, true) : ADF[pg](t); } catch (e) { globalThis.__asciiErr = String(e); return ''; }
}
